			return protocol.MakeArgNumErrReply(cmdName)
		}
		return execMulti(db, c)
	} else if cmdName == "watch" {
		if !validateArity(-2, cmdLine) {
			return protocol.MakeArgNumErrReply(cmdName)
		}
		return Watch(db, c, cmdLine[1:])
	}

	// normal commands
	cmdNameBytes := cmdLine[0]
	cmdFunc, ok := cmdTable[strings.ToLower(string(cmdNameBytes))]
	if !ok {
		return protocol.MakeErrReply("ERR unknown command '" + string(cmdNameBytes) + "'")
	}
	if !validateArity(cmdFunc.arity, cmdLine) {
		return protocol.MakeArgNumErrReply(string(cmdNameBytes))
	}
	prepare := cmdFunc.prepare
	write, read := prepare(cmdLine[1:])
	db.RWLocks(write, read)
	defer db.RWUnLocks(write, read)
	fun := cmdFunc.executor
	return fun(db, cmdLine[1:])
}

// AfterClientClose does some clean after client close connection
func (db *DB) AfterClientClose(c redis.Connection) {
	UnWatch(db, c)
}

func validateArity(arity int, cmdArgs [][]byte) bool {
	argNum := len(cmdArgs)
	if arity >= 0 {
		return argNum == arity
	}
	return argNum >= -arity
}

/* ---- data Access ---- */

// GetEntity returns DataEntity for given key, make sure to call GetExpires if needed
func (db *DB) GetEntity(key string) (*database.DataEntity, bool) {
	raw, ok := db.data.GetWithLock(key)
	if !ok {
		return nil, false
	}
	entity, _ := raw.(*database.DataEntity)
	return entity, true
}

// PutEntity a DataEntity into DB
func (db *DB) PutEntity(key string, entity *database.DataEntity) int {
	ret := db.data.PutWithLock(key, entity)
	// db.insertCallback may be set as nil, during `if` and actually callback
	// so introduce a local variable `cb`
	db.callbackMu.RLock()
	cb := db.insertCallback
	db.callbackMu.RUnlock()
	if ret > 0 && cb != nil {
		cb(db.index, key, entity)
	}
	return ret
}

// PutIfExists edit an existing DataEntity
func (db *DB) PutIfExists(key string, entity *database.DataEntity) int {
	return db.data.PutIfExistsWithLock(key, entity)
}

// PutIfAbsent insert an DataEntity only if the key not exists
func (db *DB) PutIfAbsent(key string, entity *database.DataEntity) int {
	ret := db.data.PutIfAbsentWithLock(key, entity)
	// db.insertCallback may be set as nil, during `if` and actually callback
	// so introduce a local variable `cb`
	db.callbackMu.RLock()
	cb := db.insertCallback
	db.callbackMu.RUnlock()
	if ret > 0 && cb != nil {
		cb(db.index, key, entity)
	}
	return ret
}

// Remove the given key from db
func (db *DB) Remove(key string) {
	raw, deleted := db.data.RemoveWithLock(key)
	db.ttlMap.Remove(key)
	taskKey := genExpireTask(key)
	timewheel.Cancel(taskKey)
	db.callbackMu.RLock()
	cb := db.deleteCallback
	db.callbackMu.RUnlock()
	if cb != nil {
		var entity *database.DataEntity
		if deleted > 0 {
			entity = raw.(*database.DataEntity)
		}
		cb(db.index, key, entity)
	}
}

// Removes the given list of keys from db
func (db *DB) Removes(keys []string) (deleted int) {
	deleted = db.data.RemovesWithLock(keys)
	for _, key := range keys {
		db.ttlMap.Remove(key)
		taskKey := genExpireTask(key)
		timewheel.Cancel(taskKey)
	}
	db.callbackMu.RLock()
	cb := db.deleteCallback
	db.callbackMu.RUnlock()
	if cb != nil {
		// Note: For simplicity, we pass nil as entity for batch removals
		for _, key := range keys {
			cb(db.index, key, nil)
		}
	}
	return deleted
}

